package testdata

// Cloud Function Weaponization test cases — issue #1782
//
// Taxonomy: unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization
//
// Covers: AWS Lambda create-function and add-permission (public),
// GCP gcloud functions/run deploy (--allow-unauthenticated → BLOCK,
// authenticated → AUDIT), az functionapp create, serverless deploy.

var CloudFunctionWeaponizationCases = []TestCase{
	// TP — BLOCK: gcloud functions deploy --allow-unauthenticated (public)
	{
		ID:               "TP-CLOUD-FN-001",
		Command:          "gcloud functions deploy data-hook --trigger-http --allow-unauthenticated --runtime python311 --region us-central1",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "gcloud functions deploy --allow-unauthenticated creates a public internet-accessible GCP function — highest-risk serverless deployment.",
		Tags:             []string{"tp", "cloud-function", "block", "gcp"},
	},
	{
		ID:               "TP-CLOUD-FN-002",
		Command:          "gcloud run deploy backdoor-svc --image gcr.io/proj/x --allow-unauthenticated",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "gcloud run deploy --allow-unauthenticated deploys a public Cloud Run service accessible without auth.",
		Tags:             []string{"tp", "cloud-function", "block", "gcp", "cloud-run"},
	},
	// TP — BLOCK: aws lambda add-permission --principal '*'
	{
		ID:               "TP-CLOUD-FN-003",
		Command:          "aws lambda add-permission --function-name my-func --principal '*' --action lambda:InvokeFunction --statement-id pub",
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda add-permission --principal '*' grants any internet caller invoke access — turns private Lambda into public endpoint.",
		Tags:             []string{"tp", "cloud-function", "block", "aws", "lambda"},
	},
	{
		ID:               "TP-CLOUD-FN-004",
		Command:          `aws lambda add-permission --function-name backdoor --principal "*" --action lambda:InvokeFunction --statement-id open`,
		ExpectedDecision: "BLOCK",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda add-permission --principal \"*\" (double-quoted) — same public grant, different quoting style.",
		Tags:             []string{"tp", "cloud-function", "block", "aws", "lambda"},
	},
	// TP — AUDIT: aws lambda create-function
	{
		ID:               "TP-CLOUD-FN-005",
		Command:          "aws lambda create-function --function-name exfil-relay --runtime python3.12 --role arn:aws:iam::123:role/exec --handler app.handler --zip-file fileb://code.zip",
		ExpectedDecision: "AUDIT",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda create-function deploys a new persistent Lambda — requires human review to confirm it is not a backdoor.",
		Tags:             []string{"tp", "cloud-function", "audit", "aws", "lambda"},
	},
	{
		ID:               "TP-CLOUD-FN-006",
		Command:          "aws lambda create-function --function-name backdoor --runtime nodejs20.x --role arn:aws:iam::456:role/r --handler index.handler --zip-file fileb://fn.zip",
		ExpectedDecision: "AUDIT",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda create-function with nodejs runtime — another new Lambda creation requiring audit.",
		Tags:             []string{"tp", "cloud-function", "audit", "aws", "lambda"},
	},
	// TP — AUDIT: gcloud functions deploy (authenticated, no --allow-unauthenticated)
	{
		ID:               "TP-CLOUD-FN-007",
		Command:          "gcloud functions deploy my-processor --trigger-http --runtime python311 --region us-central1",
		ExpectedDecision: "AUDIT",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "gcloud functions deploy without --allow-unauthenticated — authenticated deployment still requires human review.",
		Tags:             []string{"tp", "cloud-function", "audit", "gcp"},
	},
	// TP — AUDIT: az functionapp create
	{
		ID:               "TP-CLOUD-FN-008",
		Command:          "az functionapp create --name my-func --storage-account mystg --consumption-plan-location eastus --resource-group mygroup --runtime python",
		ExpectedDecision: "AUDIT",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "az functionapp create provisions a new Azure Function App — persistent serverless host requiring human review.",
		Tags:             []string{"tp", "cloud-function", "audit", "azure"},
	},
	// TP — AUDIT: serverless deploy
	{
		ID:               "TP-CLOUD-FN-009",
		Command:          "serverless deploy --stage prod",
		ExpectedDecision: "AUDIT",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "serverless deploy provisions cloud functions via the Serverless Framework — human review required.",
		Tags:             []string{"tp", "cloud-function", "audit", "serverless"},
	},
	{
		ID:               "TP-CLOUD-FN-010",
		Command:          "sls deploy --stage production --region us-east-1",
		ExpectedDecision: "AUDIT",
		Classification:   "TP",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "sls (short for serverless) deploy — same threat as serverless deploy.",
		Tags:             []string{"tp", "cloud-function", "audit", "serverless"},
	},
	// TN — safe cloud operations that must NOT be blocked by our new rules.
	// Note: AWS/GCP/Azure CLI calls get AUDIT from pre-existing cloud-recon and
	// aws-cli audit rules — ExpectedDecision reflects the engine's actual output
	// so these test that our new rules don't promote anything to BLOCK.
	{
		ID:               "TN-CLOUD-FN-001",
		Command:          "aws lambda list-functions",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda list-functions — read-only operation. Gets AUDIT from pre-existing ne-audit-aws-cli rule; must not be BLOCK.",
		Tags:             []string{"tn", "safe", "aws", "lambda"},
	},
	{
		ID:               "TN-CLOUD-FN-002",
		Command:          "aws lambda get-function --function-name my-func",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda get-function — read-only inspection. Gets AUDIT from pre-existing aws-cli rule; must not be BLOCK.",
		Tags:             []string{"tn", "safe", "aws", "lambda"},
	},
	{
		ID:               "TN-CLOUD-FN-003",
		Command:          "aws lambda add-permission --function-name my-func --principal apigateway.amazonaws.com --action lambda:InvokeFunction --statement-id apigw",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda add-permission with specific AWS service principal (not wildcard). Gets AUDIT from aws-cli rule; must not be BLOCK by our wildcard-principal rule.",
		Tags:             []string{"tn", "safe", "aws", "lambda"},
	},
	{
		ID:               "TN-CLOUD-FN-004",
		Command:          "gcloud functions describe my-function --region us-central1",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "gcloud functions describe — read-only inspection. Gets AUDIT from pre-existing gcloud rule; must not be BLOCK.",
		Tags:             []string{"tn", "safe", "gcp"},
	},
	{
		ID:               "TN-CLOUD-FN-005",
		Command:          "az functionapp show --name my-app --resource-group mygroup",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "az functionapp show — read-only. Gets AUDIT from pre-existing az-cli rule; must not be BLOCK.",
		Tags:             []string{"tn", "safe", "azure"},
	},
	{
		ID:               "TN-CLOUD-FN-006",
		Command:          "serverless info --stage prod",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "serverless info — read-only query. Gets default AUDIT (no specific rule); must not be BLOCK.",
		Tags:             []string{"tn", "safe", "serverless"},
	},
	{
		ID:               "TN-CLOUD-FN-007",
		Command:          "git commit -m 'block gcloud functions deploy --allow-unauthenticated'",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "DOC_CONTEXT: git commit mentioning --allow-unauthenticated — excluded by DOC_CONTEXT macro. Gets default AUDIT; must not be BLOCK.",
		Tags:             []string{"tn", "safe", "doc-context"},
	},
	{
		ID:               "TN-CLOUD-FN-008",
		Command:          "echo 'aws lambda create-function creates new function'",
		ExpectedDecision: "ALLOW",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "DOC_CONTEXT: echo mentioning aws lambda create-function — excluded by DOC_CONTEXT macro. Must not trigger AUDIT/BLOCK.",
		Tags:             []string{"tn", "safe", "doc-context"},
	},
	{
		ID:               "TN-CLOUD-FN-009",
		Command:          "aws lambda update-function-code --function-name my-func --zip-file fileb://new.zip",
		ExpectedDecision: "AUDIT",
		Classification:   "TN",
		TaxonomyRef:      "unauthorized-execution/agentic-attacks/agent-cloud-function-weaponization",
		Analyzer:         "regex",
		Description:      "aws lambda update-function-code updates existing code (not create). Gets AUDIT from pre-existing aws-cli rule; must not be BLOCK by our create-function rule.",
		Tags:             []string{"tn", "safe", "aws", "lambda"},
	},
}
